/* ===== V18 — marketer referral links (?ref=CODE on any page). First touch wins for 30 days; customers see nothing. ===== */
const REF_RE=/^[a-z0-9-]{2,20}$/,REF_KEY='zx_ref',REF_DAYS=30;
const cleanRef=v=>{const s=String(v??'').trim().toLowerCase();return REF_RE.test(s)?s:''};
function storedRef(){try{const o=JSON.parse(localStorage.getItem(REF_KEY)||'null');if(o&&REF_RE.test(o.code||'')&&+o.ts&&Date.now()-o.ts<REF_DAYS*864e5)return o.code}catch{}return ''}
(function captureRef(){try{const u=new URL(location.href);if(!u.searchParams.has('ref'))return;const code=cleanRef(u.searchParams.get('ref'));if(code&&!storedRef())localStorage.setItem(REF_KEY,JSON.stringify({code,ts:Date.now()}));u.searchParams.delete('ref');history.replaceState(history.state,'',u.pathname+u.search+u.hash)}catch{}})();

