function renderAcademies(){document.getElementById('app').innerHTML=shell()+`<main><section class="page-hero"><div class="container"><span class="eyebrow">ZERO X ACADEMIES</span><h1>علامة واحدة. <span class="accent">تجربتان محليتان</span>.</h1><p class="muted lead">نعمل على تجهيز أكاديميات ZERO X في دمشق واللاذقية. لم تُعلن العناوين التفصيلية أو مواعيد الافتتاح بعد، ويمكنك تسجيل اهتمامك ليتم التواصل معك عند توفر التفاصيل.</p><div class="hero-cta"><a class="btn btn-primary" href="#branch-interest">سجّل اهتمامك</a><a class="btn btn-outline" href="academy.html">استعرض البرامج الحالية</a></div></div></section><section class="section"><div class="container"><div class="section-head"><div><span class="eyebrow">OUR LOCATIONS</span><h2>الأكاديميات قيد التجهيز</h2></div><p>نثبت المدينة المستهدفة الآن، ونضيف العنوان والخريطة ومواعيد التسجيل بعد اعتمادها رسميًا.</p></div><div class="branch-grid" style="grid-template-columns:repeat(auto-fit,minmax(260px,1fr))"><article class="card branch-card" style="border:2px solid var(--red);box-shadow:0 10px 30px rgba(166,15,42,.15)"><div class="branch-top"><span class="tag" style="background:var(--red);color:#fff;font-weight:700">● مفتوحة الآن</span><span class="branch-mark">ZERO X</span></div><div class="city-mark" aria-hidden="true">01</div><h3>أكاديمية ZERO X — منبج</h3><p class="muted"><svg width="16" height="16" viewBox="0 0 24 24" fill="var(--red)" style="vertical-align:-2px;margin-left:4px"><path d="M12 2C8.1 2 5 5.1 5 9c0 5.2 7 13 7 13s7-7.8 7-13c0-3.9-3.1-7-7-7zm0 9.5A2.5 2.5 0 1 1 12 6.5a2.5 2.5 0 0 1 0 5z"/></svg>منبج — سنتر الشهباء، الطابق الأول.<br>الدورات قائمة والتسجيل مفتوح الآن.</p><a class="btn btn-primary" href="academies.html#branch-interest">سجّل الآن</a></article><article class="card branch-card"><div class="branch-top"><span class="tag status-planning">قيد التجهيز</span><span class="branch-mark">ZERO X</span></div><div class="city-mark" aria-hidden="true">02</div><h3>أكاديمية ZERO X — دمشق</h3><p class="muted">الفرع المستهدف في دمشق. سيُعلن العنوان التفصيلي ومواعيد بدء التسجيل بعد اعتماد الموقع وتجهيز البرنامج التشغيلي.</p><ul class="checklist"><li>المدينة محددة: دمشق</li><li>العنوان التفصيلي: سيُعلن لاحقًا</li><li>مواعيد التسجيل: قيد التحديد</li></ul><button class="btn btn-primary" type="button" data-prefill-city="دمشق">سجّل اهتمامك بفرع دمشق</button></article><article class="card branch-card"><div class="branch-top"><span class="tag status-planning">قيد التجهيز</span><span class="branch-mark">ZERO X</span></div><div class="city-mark" aria-hidden="true">03</div><h3>أكاديمية ZERO X — اللاذقية</h3><p class="muted">الفرع المستهدف في اللاذقية. ستُضاف معلومات الموقع والخدمات ومواعيد التسجيل عندما تُعتمد رسميًا.</p><ul class="checklist"><li>المدينة محددة: اللاذقية</li><li>العنوان التفصيلي: سيُعلن لاحقًا</li><li>مواعيد التسجيل: قيد التحديد</li></ul><button class="btn btn-primary" type="button" data-prefill-city="اللاذقية">سجّل اهتمامك بفرع اللاذقية</button></article></div></div></section><section class="section soft" id="branch-interest"><div class="container"><div class="section-head"><div><span class="eyebrow">REGISTER YOUR INTEREST</span><h2>سجّل اهتمامك أو استفسارك</h2></div><p>املأ النموذج، وسيتم حفظ الطلب في لوحة الإدارة ليتواصل معك الفريق. إرسال النموذج لا يعني حجز مقعد أو تأكيد افتتاح الفرع.</p></div><div class="lead-layout"><div class="card lead-info"><div class="icon">ZX</div><h3>خلّينا نساعدك تختار الخطوة المناسبة</h3><p class="muted">سواء كنت مهتمًا بفرع دمشق أو اللاذقية، أو بالدراسة عن بُعد، أخبرنا باهتمامك حتى نتابع معك عند توفر المعلومات المناسبة.</p><ul class="checklist"><li>اختر المدينة التي تناسبك</li><li>حدّد نوع الخدمة أو البرنامج</li><li>اكتب وسيلة تواصل صحيحة</li><li>سيظهر الطلب للفريق في لوحة الإدارة</li></ul><div class="notice">لا ترسل كلمات مرور أو معلومات مالية حساسة في هذا النموذج.</div></div><div class="card"><form id="leadForm" class="form lead-form" novalidate><div class="field"><label for="leadName">الاسم</label><input id="leadName" name="name" autocomplete="name" maxlength="80" required placeholder="اسمك"></div><div class="field"><label for="leadContact">وسيلة التواصل</label><input id="leadContact" name="contact" maxlength="120" required placeholder="رقم هاتف أو اسم مستخدم أو بريد إلكتروني"></div><div class="field"><label for="leadContactMethod">كيف تفضّل أن نتواصل معك؟</label><select id="leadContactMethod" name="contactMethod" required><option value="Telegram">Telegram</option><option value="Instagram">Instagram</option><option value="واتساب">واتساب</option><option value="اتصال هاتفي">اتصال هاتفي</option><option value="البريد الإلكتروني">البريد الإلكتروني</option></select></div><div class="field"><label for="leadCity">المدينة أو نمط الدراسة</label><select id="leadCity" name="city" required><option value="">اختر الخيار المناسب</option><option value="منبج">منبج</option><option value="دمشق">دمشق</option><option value="اللاذقية">اللاذقية</option><option value="التعليم عن بُعد">التعليم عن بُعد</option><option value="مدينة أخرى">مدينة أخرى</option></select></div><div class="field"><label for="leadInterest">ما الذي تهتم به؟</label><select id="leadInterest" name="interest" required><option value="البرامج التعليمية">البرامج التعليمية</option><option value="الاستشارات التعليمية">الاستشارات التعليمية</option><option value="التدريب العملي والباك تيست">التدريب العملي والباك تيست</option><option value="افتتاح فرع في المدينة">افتتاح الفرع / التسجيل عند توفره</option><option value="خدمات أخرى">خدمات أخرى</option></select></div><div class="field"><label for="leadMessage">ملاحظة إضافية (اختياري)</label><textarea id="leadMessage" name="message" rows="4" maxlength="500" placeholder="اكتب أي سؤال أو تفاصيل تساعدنا على الرد عليك"></textarea></div><div class="lead-honey" aria-hidden="true"><label for="leadWebsite">اترك هذا الحقل فارغًا</label><input id="leadWebsite" name="website" tabindex="-1" autocomplete="off"></div><label class="consent-row"><input id="leadConsent" type="checkbox" required><span>أوافق على استخدام بيانات التواصل التي أدخلتها للرد على استفساري.</span></label><div id="leadMsg" class="notice form-message" role="status" aria-live="polite" style="display:none"></div><button class="btn btn-primary" type="submit" style="width:100%">إرسال الاستفسار</button><p class="muted privacy-hint">لن يظهر رقم التواصل علنًا. يطّلع على الطلب الفريق المخوّل بالمتابعة فقط.</p></form></div></div></div></section><section class="section"><div class="container"><div class="section-head"><div><span class="eyebrow">ONE STANDARD</span><h2>ما الذي نعمل على توحيده؟</h2></div><p>هدفنا أن يحصل الطالب على تجربة منظمة وواضحة في كل فرع، مع اختلاف التفاصيل المحلية بحسب جاهزية كل موقع.</p></div><div class="grid3"><article class="card"><div class="icon">01</div><h3>منهج تعليمي واضح</h3><p class="muted">برامج موضّحة المحتوى والمستوى والتوقعات قبل التسجيل.</p></article><article class="card"><div class="icon">02</div><h3>متابعة منظّمة</h3><p class="muted">تحديد قنوات التواصل وطريقة الدعم وآلية متابعة تقدم الطالب.</p></article><article class="card"><div class="icon">03</div><h3>شفافية في الخدمات</h3><p class="muted">عرض الأسعار والشروط ومخاطر التداول بوضوح، دون وعود بأرباح مضمونة.</p></article></div></div></section></main>`+footer();
  const initialCity=new URLSearchParams(location.search).get('city');if(['دمشق','اللاذقية'].includes(initialCity)){const citySelect=document.getElementById('leadCity');if(citySelect)citySelect.value=initialCity;}
  document.querySelectorAll('[data-prefill-city]').forEach(btn=>btn.addEventListener('click',()=>{const city=document.getElementById('leadCity');if(city)city.value=btn.dataset.prefillCity;document.getElementById('branch-interest')?.scrollIntoView({behavior:'smooth'});document.getElementById('leadName')?.focus({preventScroll:true});}));
  if(location.hash==='#branch-interest')document.getElementById('branch-interest')?.scrollIntoView({behavior:'auto'});
  document.getElementById('leadForm')?.addEventListener('submit',async e=>{e.preventDefault();const form=e.currentTarget;const msg=document.getElementById('leadMsg');const submit=form.querySelector('button[type="submit"]');msg.style.display='none';if(!form.reportValidity())return;if(!document.getElementById('leadConsent').checked){msg.textContent='يرجى الموافقة على استخدام بيانات التواصل للرد على استفسارك.';msg.style.display='block';return;}submit.disabled=true;submit.textContent='جارٍ إرسال الاستفسار...';try{if(!document.getElementById('leadWebsite').value){const F=await fb();await F.createLead({type:'inquiry',name:document.getElementById('leadName').value,contact:document.getElementById('leadContact').value,contactMethod:document.getElementById('leadContactMethod').value,city:document.getElementById('leadCity').value,interest:document.getElementById('leadInterest').value,message:document.getElementById('leadMessage').value,ref:storedRef()});}msg.classList.add('is-ok');msg.textContent='وصل استفسارك بنجاح. شكرًا لاهتمامك بـ ZERO X؛ سيتواصل معك الفريق عبر الوسيلة التي اخترتها عند مراجعة الطلب.';msg.style.display='block';form.reset();}catch(err){msg.classList.remove('is-ok');msg.textContent=leadErr(err);msg.style.display='block';}finally{submit.disabled=false;submit.textContent='إرسال الاستفسار';}});
}
const SY_CITIES=['دمشق','ريف دمشق','حلب','منبج','اللاذقية','طرطوس','حمص','حماة','إدلب','الرقة','دير الزور','الحسكة','القامشلي','درعا','السويداء','خارج سوريا'];
function renderAuth(mode){const reg=mode==='register';document.getElementById('app').innerHTML=shell()+`<main class="auth-wrap"><div class="auth-card"><span class="eyebrow">ZERO X ACCOUNT</span><h1 style="font-size:34px">${reg?'إنشاء حساب':'تسجيل الدخول'}</h1><p class="muted" style="margin-top:-6px">${reg?'حساب واحد لتسجيل دوراتك ومتابعة دفعاتك.':'أهلًا من جديد 👋'}</p><form id="authForm" novalidate>${reg?`<div class="field"><label for="name">الاسم الكامل</label><input id="name" autocomplete="name" required maxlength="80"></div><div class="field"><label for="phone">رقم الواتساب</label><input id="phone" type="tel" dir="ltr" inputmode="tel" autocomplete="tel" placeholder="+963 9xx xxx xxx" required maxlength="25"></div><div class="field"><label for="city">المدينة</label><input id="city" list="cityList" autocomplete="address-level2" required maxlength="60"><datalist id="cityList">${SY_CITIES.map(c=>`<option value="${c}">`).join('')}</datalist></div>`:''}<div class="field"><label for="email">البريد الإلكتروني</label><input id="email" type="email" dir="ltr" autocomplete="email" required></div><div class="field"><label for="password">كلمة المرور</label><input id="password" type="password" dir="ltr" minlength="6" autocomplete="${reg?'new-password':'current-password'}" required>${reg?'<small class="muted">6 أحرف على الأقل</small>':''}</div><div id="authError" class="notice" style="display:none;margin-bottom:15px" role="alert"></div><button class="btn btn-primary" id="authSubmit" style="width:100%">${reg?'إنشاء الحساب':'دخول'}</button></form>${reg?`<p class="muted" style="font-size:14px;margin-top:18px">عندك حساب؟ <a class="accent-link" href="login.html${location.search}">سجّل الدخول</a></p>`:`<p class="muted" style="font-size:14px;margin-top:18px;display:flex;justify-content:space-between;gap:10px;flex-wrap:wrap"><a class="accent-link" href="register.html${location.search}">إنشاء حساب جديد</a><a href="#" id="forgotPw">نسيت كلمة المرور؟</a></p>`}</div></main>`+footer();
  const form=document.getElementById('authForm'),err=document.getElementById('authError'),btn=document.getElementById('authSubmit');const val=id=>(document.getElementById(id)?.value||'').trim();
  whoami().then(w=>{if(w&&w.profile)location.replace(safeNext('dashboard.html'))}).catch(()=>{});
  document.getElementById('forgotPw')?.addEventListener('click',async e=>{e.preventDefault();const email=val('email');if(!email){showMsg(err,'اكتب بريدك الإلكتروني بالأعلى أولًا، ثم اضغط «نسيت كلمة المرور؟».');return;}try{const F=await fb();await F.resetPassword(email);showMsg(err,'📩 أرسلنا رابط تغيير كلمة المرور إلى بريدك (تفقد مجلد Spam أيضًا).',true)}catch(x){showMsg(err,fbErr(x))}});
  form.addEventListener('submit',async e=>{e.preventDefault();err.style.display='none';if(!form.reportValidity())return;btn.disabled=true;const label=btn.textContent;btn.textContent=reg?'جارٍ إنشاء الحساب...':'جارٍ الدخول...';
    let F;try{F=await fb()}catch(x){showMsg(err,fbErr(x));btn.disabled=false;btn.textContent=label;return}
    try{
      if(reg&&val('phone').replace(/[^0-9]/g,'').length<7){showMsg(err,'اكتب رقم واتساب صحيح مع رمز الدولة، مثل: +963 944 123 456');btn.disabled=false;btn.textContent=label;return}
      if(reg){const p={name:val('name'),phone:val('phone'),city:val('city'),email:val('email')};const rf=storedRef();if(rf)p.ref=rf;localStorage.setItem('zx_pending_profile',JSON.stringify(p));await F.register({...p,password:document.getElementById('password').value});localStorage.removeItem('zx_pending_profile');localStorage.setItem('zx_auth','student');}
      else{await F.login(val('email'),document.getElementById('password').value);localStorage.setItem('zx_auth','student');}
      location.href=safeNext('dashboard.html');
    }catch(x){
      if(reg&&F.currentUser()){location.href=safeNext('dashboard.html');return;} // account created; profile is completed on the account page
      showMsg(err,fbErr(x));btn.disabled=false;btn.textContent=label;}
  });
}

function courseStatusMap(pays){const rank={confirmed:3,pending:2,rejected:1};const m={};pays.forEach(p=>{if(isConsult(p))return;const cur=m[p.course];if(!cur||rank[p.status]>rank[cur.status])m[p.course]=p});return m}
async function renderDashboard(){
  const app=document.getElementById('app');
  app.innerHTML=shell()+`<main class="dash"><aside class="dash-side"><strong>لوحة الطالب</strong><a class="active" href="#top">حسابي</a><a href="#myCourses">دوراتي</a><a href="#myConsults">استشاراتي</a><a href="#myPayments">دفعاتي</a><a href="#subscribe">اشترك بدورة</a><a href="academy.html">استكشف الدورات</a><span id="sideAdmin"></span><button class="btn btn-outline" data-logout style="margin-top:10px;width:100%">تسجيل الخروج</button></aside><section class="dash-main" id="top"><h1 style="font-size:38px" id="dashWelcome">أهلًا 👋</h1><p class="muted">هنا تظهر بياناتك ودوراتك ودفعاتك وحالتها.</p><div id="dashBody"><div class="empty">جارٍ تحميل حسابك...</div></div></section></main>`+footer();
  document.querySelectorAll('[data-logout]').forEach(b=>b.onclick=e=>{e.preventDefault();doLogout()});
  const body=document.getElementById('dashBody');
  let w;try{w=await whoami()}catch(x){body.innerHTML=`<div class="notice zx-msg err">${esc(fbErr(x))}</div>`;return}
  if(!w){location.replace('login.html?next='+encodeURIComponent('dashboard.html'+location.search+location.hash));return}
  if(w.role==='admin')document.getElementById('sideAdmin').innerHTML='<a href="admin.html">🛠 لوحة الأدمن</a>';
  const F=await fb();
  // Profile doc missing (e.g. created while the database was not ready): finish it now.
  if(!w.profile){
    let pend=null;try{pend=JSON.parse(localStorage.getItem('zx_pending_profile')||'null')}catch{}
    if(pend&&pend.name&&(!pend.email||String(pend.email).toLowerCase()===String(w.email).toLowerCase())){try{await F.saveProfile(w.uid,{...pend,email:w.email,ref:pend.ref||storedRef()});localStorage.removeItem('zx_pending_profile');w=await whoami(true)}catch(x){body.innerHTML=`<div class="notice zx-msg err">تم إنشاء حسابك، لكن تعذّر حفظ بياناتك: ${esc(fbErr(x))}</div>`;return}}
  }
  if(!w.profile){
    if(w.profileError){body.innerHTML=`<div class="notice zx-msg err">${esc(fbErr(w.profileError))}</div>`;return}
    body.innerHTML=`<div class="card"><h2>أكمل بياناتك</h2><p class="muted">نحتاجها لتفعيل دوراتك والتواصل معك.</p><form id="completeForm"><div class="field"><label for="cName">الاسم الكامل</label><input id="cName" required maxlength="80"></div><div class="field"><label for="cPhone">رقم الواتساب</label><input id="cPhone" type="tel" dir="ltr" required maxlength="25" placeholder="+963 9xx xxx xxx"></div><div class="field"><label for="cCity">المدينة</label><input id="cCity" list="cityList2" required maxlength="60"><datalist id="cityList2">${SY_CITIES.map(c=>`<option value="${c}">`).join('')}</datalist></div><div id="cMsg" class="notice" style="display:none;margin-bottom:15px"></div><button class="btn btn-primary">حفظ</button></form></div>`;
    document.getElementById('completeForm').addEventListener('submit',async e=>{e.preventDefault();if(!e.target.reportValidity())return;try{await F.saveProfile(w.uid,{name:document.getElementById('cName').value.trim(),phone:document.getElementById('cPhone').value.trim(),city:document.getElementById('cCity').value.trim(),email:w.email,ref:storedRef()});await whoami(true);renderDashboard()}catch(x){showMsg(document.getElementById('cMsg'),fbErr(x))}});
    return;
  }
  const P=w.profile;document.getElementById('dashWelcome').textContent=`أهلًا ${P.name||''} 👋`;
  let pays=[],payErr=null;try{pays=await F.myPayments(w.uid)}catch(x){payErr=x}
  const cmap=courseStatusMap(pays);const myCourses=Object.values(cmap);const myConsults=pays.filter(isConsult);
  const preset=new URLSearchParams(location.search).get('course');
  body.innerHTML=`<div class="statgrid"><div class="stat"><small class="muted">دورات مفعّلة</small><strong class="zx-num">${myCourses.filter(x=>x.status==='confirmed').length}</strong></div><div class="stat"><small class="muted">بانتظار التأكيد</small><strong class="zx-num">${pays.filter(x=>x.status==='pending').length}</strong></div><div class="stat"><small class="muted">كل الدفعات</small><strong class="zx-num">${pays.length}</strong></div></div>
  ${payErr?`<div class="notice zx-msg err" style="margin-top:20px">${esc(fbErr(payErr))}</div>`:''}
  <div class="card zx-card"><h2>بياناتي</h2><dl class="zx-dl"><div><dt>الاسم</dt><dd>${esc(P.name)}</dd></div><div><dt>واتساب</dt><dd dir="ltr">${esc(P.phone)}</dd></div><div><dt>المدينة</dt><dd>${esc(P.city)}</dd></div><div><dt>البريد</dt><dd dir="ltr">${esc(P.email||w.email)}</dd></div></dl></div>
  <div class="card zx-card" id="myCourses"><h2>دوراتي</h2>${myCourses.length?`<div class="zx-rows">${myCourses.map(p=>`<div class="zx-row"><strong>${esc(courseTitle(p.course))}</strong><span class="zx-badge s-${esc(p.status)}">${COURSE_STATUS[p.status]||esc(p.status)}</span></div>`).join('')}</div>`:'<div class="empty">لم تشترك بأي دورة بعد. اختر دورة من الأسفل 👇</div>'}</div>
  <div class="card zx-card" id="myConsults"><h2>استشاراتي</h2>${myConsults.length?`<div class="zx-rows">${myConsults.map(p=>`<div class="zx-row"><div><strong>${esc(CONSULT.title)}${p.consultType?' — '+esc(p.consultType):''}</strong><div class="muted" style="font-size:13px">${esc(p.method)} · $${esc(p.price)} · ${fmtDate(p.createdAt)}</div>${p.status==='confirmed'?'<div class="muted" style="font-size:13px">رح نتواصل معك لتحديد موعد الجلسة.</div>':''}</div><span class="zx-badge s-${esc(p.status)}">${CONSULT_STATUS[p.status]||esc(p.status)}</span></div>`).join('')}</div><a class="btn btn-outline" style="margin-top:14px" href="consultation.html">طلب استشارة جديدة</a>`:'<div class="empty">ما طلبت استشارة بعد. <a href="consultation.html" style="color:var(--red);font-weight:700">اطلب استشارة خاصة — $20</a></div>'}</div>
  <div class="card zx-card" id="myPayments"><h2>دفعاتي</h2>${pays.length?`<div class="zx-rows">${pays.map(p=>`<div class="zx-row"><div><strong>${esc(courseTitle(p.course))}</strong><div class="muted" style="font-size:13px">${esc(p.method)} · ${p.price?'$'+esc(p.price)+' · ':''}${fmtDate(p.createdAt)}</div></div><span class="zx-badge s-${esc(p.status)}">${PAY_STATUS[p.status]||esc(p.status)}</span></div>`).join('')}</div>`:'<div class="empty">لا توجد دفعات بعد.</div>'}</div>
  <div class="card zx-card" id="subscribe"><h2>اشترك بدورة</h2><form id="subForm"><div class="field"><label for="subCourse">الدورة</label><select id="subCourse" required>${ENROLL_COURSES.map(id=>`<option value="${id}" ${id===preset?'selected':''}>${esc(courses[id].title)} — $${courses[id].price}</option>`).join('')}</select></div><div class="field"><label for="subMethod">طريقة الدفع</label><select id="subMethod" required>${PAY_METHODS.map(m=>`<option value="${esc(m.id)}">${esc(m.label)}</option>`).join('')}</select></div><div id="payBox"></div><div class="field"><label for="subNote">ملاحظة (اختياري)</label><textarea id="subNote" rows="3" maxlength="500" placeholder="مثلًا: دفعت من حساب أخي، أو بدي أدفع على دفعتين"></textarea></div><div id="subMsg" class="notice" style="display:none;margin-bottom:15px" role="alert"></div><button class="btn btn-primary" id="subBtn" style="width:100%">إرسال طلب الاشتراك</button><p class="muted" style="font-size:13px;margin-top:12px">بعد ما يتأكد الفريق من الدفعة، بتصير الدورة ✅ مفعّلة بحسابك.</p></form></div>`;
  const cSel=document.getElementById('subCourse'),mSel=document.getElementById('subMethod'),box=document.getElementById('payBox');
  const paintBox=()=>paintPayBox(box,mSel.value,courses[cSel.value].price);
  cSel.onchange=paintBox;mSel.onchange=paintBox;paintBox();
  if(location.hash==='#myConsults')setTimeout(()=>document.getElementById('myConsults').scrollIntoView({behavior:'smooth',block:'start'}),60);
  if(location.hash==='#subscribe'||preset)setTimeout(()=>document.getElementById('subscribe').scrollIntoView({behavior:'smooth',block:'start'}),60);
  document.getElementById('subForm').addEventListener('submit',async e=>{e.preventDefault();const msg=document.getElementById('subMsg'),btn=document.getElementById('subBtn');msg.style.display='none';const cid=cSel.value;const ex=cmap[cid];
    if(ex&&ex.status==='confirmed'){showMsg(msg,'هذه الدورة مفعّلة بحسابك مسبقًا ✅');return}
    if(ex&&ex.status==='pending'){showMsg(msg,'لديك طلب لهذه الدورة بانتظار التأكيد ⏳. فريقنا رح يراجعه قريبًا.');return}
    btn.disabled=true;btn.textContent='جارٍ الإرسال...';
    try{await F.createPayment({uid:w.uid,name:P.name,phone:P.phone,city:P.city,email:P.email||w.email,course:cid,courseTitle:courses[cid].title,price:courses[cid].price,method:mSel.value,note:document.getElementById('subNote').value.trim(),ref:P.ref});
      showMsg(msg,'✅ وصل طلبك! فريقنا بيتأكد من الدفعة وبيفعّل الدورة بحسابك.',true);setTimeout(()=>{history.replaceState(null,'','dashboard.html');renderDashboard().then(()=>{const m2=document.getElementById('myCourses');m2&&m2.scrollIntoView({block:'start'})})},1400)}
    catch(x){showMsg(msg,fbErr(x));btn.disabled=false;btn.textContent='إرسال طلب الاشتراك'}});
}
