  const body=document.getElementById('consultBody');
  let w;try{w=await whoami()}catch(x){body.innerHTML=`<div class="notice zx-msg err">${esc(fbErr(x))}</div>`;return}
  if(!w){location.replace('login.html?next=consultation.html');return}
  if(!w.profile){body.innerHTML=w.profileError?`<div class="notice zx-msg err">${esc(fbErr(w.profileError))}</div>`:`<div class="notice">أكمل بياناتك بحسابك أولًا (الاسم والرقم والمدينة) لنقدر نتواصل معك.</div><a class="btn btn-primary" style="margin-top:14px;width:100%" href="dashboard.html">إكمال البيانات</a>`;return}
  const F=await fb();const P=w.profile;
