    if(!problem){showMsg(msg,'اكتب مشكلتك باختصار لنحضّر للجلسة.');document.getElementById('consultProblem').focus();return}
    if(pending){showMsg(msg,'عندك طلب استشارة بانتظار التأكيد ⏳. فريقنا رح يراجعه قريبًا.');return}
    btn.disabled=true;btn.textContent='جارٍ الإرسال...';
