async function fileToDataURL(file){return new Promise((resolve,reject)=>{if(!file)return resolve('');if(file.size>5*1024*1024)return reject(new Error('حجم إثبات الدفع يجب ألا يتجاوز 5MB'));const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(new Error('تعذر قراءة الملف'));r.readAsDataURL(file);});}


function csvDownload(name,headers,rows){const cell=v=>{let s=String(v??'');if(/^[=@]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"'};const txt='\ufeff'+[headers,...rows].map(r=>r.map(cell).join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([txt],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),2000)}
