  const rangeBounds=()=>{const n=new Date(),y=n.getFullYear(),mo=n.getMonth();if(mrange==='month')return [new Date(y,mo,1).getTime(),Infinity];if(mrange==='last')return [new Date(y,mo-1,1).getTime(),new Date(y,mo,1).getTime()];if(mrange==='custom'){const p=s=>{const [a,b,c]=String(s).split('-').map(Number);return new Date(a,b-1,c).getTime()};return [mfrom?p(mfrom):-Infinity,mto?p(mto)+864e5:Infinity]}return [-Infinity,Infinity]};
  // Commission rule (Jamal, Oct 2026): basePct (25) of confirmed revenue; in a calendar month where the marketer has MORE THAN bonusThreshold (10)
